CREATE TABLE "AspNetRoles" ("Id" uuid PRIMARY KEY, "Name" varchar(256), "NormalizedName" varchar(256), "ConcurrencyStamp" text);
CREATE UNIQUE INDEX "RoleNameIndex" ON "AspNetRoles" ("NormalizedName");
CREATE TABLE "AspNetUsers" (
 "Id" uuid PRIMARY KEY, "UserName" varchar(256), "NormalizedUserName" varchar(256), "Email" varchar(256), "NormalizedEmail" varchar(256),
 "EmailConfirmed" boolean NOT NULL, "PasswordHash" text, "SecurityStamp" text, "ConcurrencyStamp" text, "PhoneNumber" text,
 "PhoneNumberConfirmed" boolean NOT NULL, "TwoFactorEnabled" boolean NOT NULL, "LockoutEnd" timestamptz, "LockoutEnabled" boolean NOT NULL, "AccessFailedCount" integer NOT NULL,
 "DisplayName" varchar(60) NOT NULL, "Status" text NOT NULL CHECK ("Status" IN ('Active','Suspended','Deleted')), "SecurityVersion" integer NOT NULL, "CreatedAt" timestamptz NOT NULL
);
CREATE UNIQUE INDEX "UserNameIndex" ON "AspNetUsers" ("NormalizedUserName");
CREATE UNIQUE INDEX "EmailIndex" ON "AspNetUsers" ("NormalizedEmail");
CREATE TABLE "AspNetRoleClaims" ("Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "RoleId" uuid NOT NULL REFERENCES "AspNetRoles" ON DELETE CASCADE, "ClaimType" text, "ClaimValue" text);
CREATE INDEX ON "AspNetRoleClaims" ("RoleId");
CREATE TABLE "AspNetUserClaims" ("Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, "UserId" uuid NOT NULL REFERENCES "AspNetUsers" ON DELETE CASCADE, "ClaimType" text, "ClaimValue" text);
CREATE INDEX ON "AspNetUserClaims" ("UserId");
CREATE TABLE "AspNetUserLogins" ("LoginProvider" text NOT NULL, "ProviderKey" text NOT NULL, "ProviderDisplayName" text, "UserId" uuid NOT NULL REFERENCES "AspNetUsers" ON DELETE CASCADE, PRIMARY KEY ("LoginProvider", "ProviderKey"));
CREATE INDEX ON "AspNetUserLogins" ("UserId");
CREATE TABLE "AspNetUserRoles" ("UserId" uuid NOT NULL REFERENCES "AspNetUsers" ON DELETE CASCADE, "RoleId" uuid NOT NULL REFERENCES "AspNetRoles" ON DELETE CASCADE, PRIMARY KEY ("UserId", "RoleId"));
CREATE INDEX ON "AspNetUserRoles" ("RoleId");
CREATE TABLE "AspNetUserTokens" ("UserId" uuid NOT NULL REFERENCES "AspNetUsers" ON DELETE CASCADE, "LoginProvider" text NOT NULL, "Name" text NOT NULL, "Value" text, PRIMARY KEY ("UserId", "LoginProvider", "Name"));
CREATE TABLE "Sessions" ("Id" uuid PRIMARY KEY, "UserId" uuid NOT NULL REFERENCES "AspNetUsers", "RefreshTokenHash" text NOT NULL UNIQUE, "FamilyId" uuid NOT NULL, "ReplacedBySessionId" uuid REFERENCES "Sessions", "CreatedAt" timestamptz NOT NULL, "ExpiresAt" timestamptz NOT NULL, "RevokedAt" timestamptz);
CREATE INDEX ON "Sessions" ("UserId");
CREATE INDEX ON "Sessions" ("FamilyId");
CREATE INDEX ON "Sessions" ("ReplacedBySessionId");
CREATE TABLE "Levels" (
 "Id" uuid PRIMARY KEY, "OwnerId" uuid NOT NULL REFERENCES "AspNetUsers", "Status" text NOT NULL CHECK ("Status" IN ('Draft','Published','Withdrawn','Deleted')),
 "CreationKey" uuid NOT NULL, "CreationHash" text NOT NULL, "PublishedRevisionId" uuid, "DraftRevisionId" uuid, "Version" integer NOT NULL CHECK ("Version" > 0),
 "CreatedAt" timestamptz NOT NULL, "UpdatedAt" timestamptz NOT NULL, "DeletedAt" timestamptz, "WithdrawnAt" timestamptz, UNIQUE ("OwnerId", "CreationKey")
);
CREATE INDEX ON "Levels" ("OwnerId", "UpdatedAt");
CREATE INDEX ON "Levels" ("Status", "UpdatedAt", "Id");
CREATE TABLE "Revisions" (
 "Id" uuid PRIMARY KEY, "LevelId" uuid NOT NULL REFERENCES "Levels", "RevisionNumber" integer NOT NULL, "Title" varchar(80) NOT NULL, "Description" varchar(2000) NOT NULL,
 "Difficulty" text NOT NULL CHECK ("Difficulty" IN ('Easy','Normal','Hard')), "State" text NOT NULL CHECK ("State" IN ('Draft','Published')),
 "Content" jsonb NOT NULL, "SchemaVersion" integer NOT NULL, "PhysicsVersion" integer NOT NULL, "ContentHash" text NOT NULL,
 "ObjectCount" integer NOT NULL CHECK ("ObjectCount" BETWEEN 0 AND 2000), "Version" integer NOT NULL, "CreatedAt" timestamptz NOT NULL, "PublishedAt" timestamptz,
 UNIQUE ("LevelId", "RevisionNumber"), UNIQUE ("LevelId", "Id")
);
CREATE UNIQUE INDEX ON "Revisions" ("LevelId") WHERE "State" = 'Draft';
ALTER TABLE "Levels" ADD FOREIGN KEY ("Id", "PublishedRevisionId") REFERENCES "Revisions" ("LevelId", "Id");
ALTER TABLE "Levels" ADD FOREIGN KEY ("Id", "DraftRevisionId") REFERENCES "Revisions" ("LevelId", "Id");
CREATE TABLE "Favorites" ("UserId" uuid NOT NULL REFERENCES "AspNetUsers", "LevelId" uuid NOT NULL REFERENCES "Levels" ON DELETE CASCADE, "CreatedAt" timestamptz NOT NULL, PRIMARY KEY ("UserId", "LevelId"));
CREATE INDEX ON "Favorites" ("UserId", "CreatedAt");
CREATE INDEX ON "Favorites" ("LevelId");
CREATE TABLE "Ratings" ("UserId" uuid NOT NULL REFERENCES "AspNetUsers", "RevisionId" uuid NOT NULL REFERENCES "Revisions", "Score" smallint NOT NULL CHECK ("Score" BETWEEN 1 AND 5), "CreatedAt" timestamptz NOT NULL, "UpdatedAt" timestamptz NOT NULL, PRIMARY KEY ("UserId", "RevisionId"));
CREATE INDEX ON "Ratings" ("RevisionId");
CREATE TABLE "Attempts" (
 "Id" uuid PRIMARY KEY, "UserId" uuid NOT NULL REFERENCES "AspNetUsers", "RevisionId" uuid NOT NULL REFERENCES "Revisions", "State" text NOT NULL CHECK ("State" IN ('Started','Finished','Abandoned','Expired')),
 "Outcome" text CHECK ("Outcome" IS NULL OR "Outcome" IN ('Dead','Completed','Quit')), "ProgressPercent" numeric NOT NULL CHECK ("ProgressPercent" BETWEEN 0 AND 100),
 "StartedAt" timestamptz NOT NULL, "FinishedAt" timestamptz, "ElapsedTicks" bigint NOT NULL CHECK ("ElapsedTicks" >= 0), "PauseTicks" bigint NOT NULL CHECK ("PauseTicks" >= 0),
 "VerificationStatus" text NOT NULL CHECK ("VerificationStatus" IN ('ClientReported','Pending','Verified','Rejected')), "PhysicsVersion" integer NOT NULL, "ContentHash" text NOT NULL, "ClientResultId" uuid
);
CREATE INDEX ON "Attempts" ("UserId", "StartedAt");
CREATE INDEX ON "Attempts" ("RevisionId", "StartedAt");
CREATE TABLE "Progress" (
 "UserId" uuid NOT NULL REFERENCES "AspNetUsers", "RevisionId" uuid NOT NULL REFERENCES "Revisions", "AttemptsCount" integer NOT NULL CHECK ("AttemptsCount" >= 0),
 "BestProgress" numeric NOT NULL CHECK ("BestProgress" BETWEEN 0 AND 100), "FirstCompletedAt" timestamptz, "LastPlayedAt" timestamptz NOT NULL,
 "LastCompletedAt" timestamptz, "CompletionCount" integer NOT NULL CHECK ("CompletionCount" >= 0), "BestVerifiedTicks" bigint, PRIMARY KEY ("UserId", "RevisionId")
);
CREATE INDEX ON "Progress" ("UserId", "LastPlayedAt");
CREATE INDEX ON "Progress" ("RevisionId");
CREATE TABLE "Audit" ("Id" uuid PRIMARY KEY, "ActorUserId" uuid REFERENCES "AspNetUsers", "Action" text NOT NULL, "TargetType" text NOT NULL, "TargetId" uuid NOT NULL, "Reason" text NOT NULL, "CorrelationId" text NOT NULL, "CreatedAt" timestamptz NOT NULL);
CREATE INDEX ON "Audit" ("ActorUserId");
